    cache = {}

    def get_div_sum(n):
        if n in cache:
            return cache[n]
        if n <= 1:
            return 0
        s = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                s += i
                if i * i != n:
                    s += n // i
        cache[n] = s
        return s

    total_sum = 0
    for a in range(2, limit + 1):
        b = get_div_sum(a)
        if b != a and get_div_sum(b) == a:
            total_sum += a

    return total_sum
